import {initSystemLab,renderSystemLab} from './system-lab.js';
import {initCommunityLab,renderCommunityLab} from './community-lab.js';
import {initRemoteLab,renderRemoteLab} from './remote-lab.js';
import {setMeteredEvidence,setDrcBenchmark,renderMeteredLab} from './metered-lab.js';
import {initFieldLab,renderFieldLab,offlineBadge,getFieldEvidence} from './field-lab.js';
import {assessmentValues,buildPassport} from './field-core.js';
import {initAILab,renderAILab,getMLEvidence} from './ai-lab.js';
import { calculateDemand, defaultInputs } from './engine.js';
const $ = (s,root=document) => root.querySelector(s);
const $$ = (s,root=document) => [...root.querySelectorAll(s)];
const escapeHtml = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=0)=>Number.isFinite(Number(v))?Number(v).toLocaleString('en-US',{maximumFractionDigits:d}):'—';
const compact=v=>v>=10000?fmt(v/1000,1)+'k':fmt(v);
const pct=v=>fmt(v*100,1)+'%';
const paths={bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7l1-7Z"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Z"/><path d="M9 3v16M15 5v16"/>',sliders:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',play:'<path d="m9 5 11 7-11 7V5Z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',save:'<path d="M5 3h12l4 4v14H3V3h2Z"/><path d="M7 3v6h10V3M7 21v-8h10v8"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M22 21v-2a4 4 0 0 0-3-3.9"/><circle cx="9" cy="7" r="4"/><path d="M16 3a4 4 0 0 1 0 8"/>',activity:'<path d="M2 12h5l3-8 4 16 3-8h5"/>',trend:'<path d="m3 17 6-6 4 4 8-10M15 5h6v6"/>',search:'<circle cx="10.5" cy="10.5" r="7"/><path d="m16 16 5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',expand:'<path d="M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',leaf:'<path d="M20 3C7 2 2 9 6 16s14 2 14-13Z"/><path d="m4 21 11-12"/>',mill:'<path d="M4 21V10l8-7 8 7v11H4ZM8 21v-7h8v7M8 9h8"/>',fridge:'<rect x="6" y="2" width="12" height="20" rx="2"/><path d="M6 9h12M9 5v2M9 12v4"/>',salon:'<circle cx="6" cy="6" r="3"/><circle cx="6" cy="18" r="3"/><path d="m8 8 12 12M8 16 20 4"/>',welding:'<path d="m14 3-7 10h6l-3 8 10-12h-7l1-6Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',book:'<path d="M12 6C8 2 3 4 3 4v15s5-2 9 2c4-4 9-2 9-2V4s-5-2-9 2ZM12 6v15"/>',external:'<path d="M14 3h7v7M10 14 21 3M21 14v7H3V3h7"/>',check:'<path d="m5 12 4 4L19 6"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>'};
const icon=(name,cls='')=>'<svg class="'+cls+'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(paths[name]||paths.bolt)+'</svg>';
const navs=[['overview','grid','Demand overview'],['villages','map','Village explorer'],['scenarios','sliders','Saved scenarios'],['field','book','Field assessment'],['ai','activity','AI model lab'],['remote','map','Satellite & drone'],['community','users','Community USSD'],['system','sliders','System feasibility'],['metered','activity','Metered evidence'],['evidence','shield','Evidence & method'],['pitch','play','Demo story']];
let sites=[],boundaries=null,survey=null,catalog=null,ramp=null,templates={};
let state={view:'overview',siteId:null,inputs:null,inspector:'assumptions',layer:'population',zoom:1,panX:0,panY:0,directoryFilter:'all',directoryQuery:'',onboarding:true};
let saved=[],customSites=[],result=null,mapBounds=null;
try{saved=JSON.parse(localStorage.getItem('aimenergy.scenarios')||'[]');if(!Array.isArray(saved))saved=[];customSites=JSON.parse(localStorage.getItem('aimenergy.custom')||'[]');if(!Array.isArray(customSites))customSites=[];}catch{saved=[];customSites=[];}
const site=()=>sites.find(s=>String(s.id)===String(state.siteId))||sites[0];
const siteForModel=()=>({...site(),population:state.populationOverride??site().population});
const statusLabel=s=>s.manual?'Manual site':s.existing?'Existing mini-grid':s.candidate?'Candidate site':'Village';
const colors={household:'#41694a',business:'#a7c96f',services:'#e2bb76'};
function calculate(){result=calculateDemand(siteForModel(),state.inputs,templates);state.inputs=result.inputs;return result;}
function persist(){try{localStorage.setItem('aimenergy.session',JSON.stringify({siteId:state.siteId,inputs:state.inputs,populationOverride:state.populationOverride,mlSource:state.mlSource,fieldEvidence:state.fieldEvidence}));}catch{}}
function toast(text){$('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=text;document.body.append(el);setTimeout(()=>el.remove(),3600);}
function selectSite(id){state.siteId=id;state.inputs=defaultInputs(site(),survey);state.populationOverride=null;state.mlSource=null;state.fieldEvidence=null;state.zoom=1;state.panX=0;state.panY=0;state.view='overview';calculate();persist();render();}
function navMarkup(mobile=false){return navs.map(([key,i,label])=>'<button class="'+(mobile?'':'nav-item ')+(state.view===key?'active':'')+'" data-action="nav" data-view="'+key+'" '+(state.view===key?'aria-current="page"':'')+' title="'+label+'">'+icon(i)+'<span>'+label+'</span></button>').join('');}
function render(){calculate();$('#app').innerHTML='<div class="shell"><aside class="rail"><div class="brand"><div class="brand-mark">'+icon('bolt')+'</div><span>Aim<span>Energy</span></span></div><div class="rail-label">PLANNING WORKSPACE</div><nav aria-label="Main navigation">'+navMarkup()+'</nav><div class="rail-bottom"><div class="rail-note">'+icon('leaf')+'<strong>Right-sized. Future-ready.</strong><p>Plan reliable power around the people who will use it.</p></div><div class="rail-footer"><span>GLOBAL ENERGY HACKATHON</span><br>Uganda pilot · 2026</div></div></aside><div class="workspace"><header class="topbar"><div class="crumb"><a href="./">Home</a><span>/</span><strong>'+escapeHtml(navs.find(n=>n[0]===state.view)?.[2]||'Demand overview')+'</strong></div><div class="top-actions"><span id="offline-pill" class="top-pill">'+offlineBadge()+'</span><span class="location">Lamwo, Uganda</span><div class="avatar" title="AimEnergy workspace">AE</div></div></header><main class="content" id="main"><div class="page-heading"><div><div class="eyebrow">BEFORE THE FIRST CONNECTION</div><h1>Power the right future.</h1><p>Understand a village’s demand. Plan for what comes next.</p></div><div class="heading-actions"><button class="btn" data-action="save" title="Save scenario">'+icon('save')+'Save scenario</button><button class="btn primary" data-action="export" title="Export planning report">'+icon('download')+'Export report</button></div></div><div id="view-content">'+viewMarkup()+'</div><footer class="footer"><span>AimEnergy · Designed for better energy access</span><span>411 real villages · Transparent scenarios · <span>Built for the field</span></span></footer></main></div><nav class="mobile-menu" aria-label="Mobile navigation">'+navMarkup(true)+'</nav></div>';if(state.view==='overview')drawMap();bindSearch();scrollActiveMobile();}
function viewMarkup(){if(state.view==='system')return renderSystemLab();if(state.view==='community')return renderCommunityLab();if(state.view==='remote')return renderRemoteLab();if(state.view==='metered')return renderMeteredLab();if(state.view==='field')return renderFieldLab();if(state.view==='ai')return renderAILab();if(state.view==='villages')return directoryView();if(state.view==='scenarios')return scenariosView();if(state.view==='evidence')return evidenceView();if(state.view==='pitch')return pitchView();return overviewView();}
function metricsMarkup(){const r=result,m=r.firstMonth,growth=r.monthly[23].totalKWh/(m.totalKWh||1)-1;return '<div class="metric"><div class="metric-label">Monthly energy · month 1<span class="metric-icon">'+icon('bolt')+'</span></div><div class="metric-value"><strong>'+fmt(m.totalKWh)+'</strong><span>kWh</span></div><div class="metric-foot">Scenario range <b>'+fmt(r.scenarios.low.firstMonth.totalKWh)+' – '+fmt(r.scenarios.high.firstMonth.totalKWh)+' kWh</b></div></div><div class="metric"><div class="metric-label">Household connections<span class="metric-icon">'+icon('users')+'</span></div><div class="metric-value"><strong>'+fmt(m.connections)+'</strong><span>households</span></div><div class="metric-foot"><b>'+fmt(state.inputs.connectionPercent)+'%</b> of '+fmt(r.potentialHouseholds)+' estimated households</div></div><div class="metric"><div class="metric-label">Average-day peak<span class="metric-icon">'+icon('activity')+'</span></div><div class="metric-value"><strong>'+fmt(m.peakKW,1)+'</strong><span>kW</span></div><div class="metric-foot">Simulated profile · <b>'+pct(m.loadFactor)+'</b> load factor</div></div><div class="metric"><div class="metric-label">Demand growth · month 24<span class="metric-icon">'+icon('trend')+'</span></div><div class="metric-value"><strong>+'+fmt(Math.max(0,growth*100))+'%</strong></div><div class="metric-foot">From '+fmt(m.totalKWh)+' to <b>'+fmt(r.monthly[23].totalKWh)+' kWh/month</b></div></div>';}
function overviewView(){const s=site();return (state.onboarding?'<div class="onboarding"><p><strong>Start with a real village.</strong> Adjust connections and business loads, then compare the next 24 months.</p><button class="close-btn" data-action="dismiss" aria-label="Dismiss introduction">×</button></div>':'')+'<section class="metrics" id="metrics" aria-label="Demand summary">'+metricsMarkup()+'</section><div class="planner"><div class="map-stack"><section class="panel"><div class="panel-head"><div><h2>Every village has a different energy story.</h2><p class="subtext">Select a settlement to explore its potential demand</p></div><span class="head-tag">'+(s.manual?'Manual location':'Lamwo district')+'</span></div><div class="map-toolbar"><div class="search-wrap">'+icon('search')+'<input id="village-search" aria-label="Search villages" placeholder="Search '+sites.length+' villages…" autocomplete="off"><div id="search-results" class="search-results" hidden></div></div><select class="layer-select" id="map-layer" aria-label="Map thematic layer"><option value="population" '+(state.layer==='population'?'selected':'')+'>Population layer</option><option value="buildings" '+(state.layer==='buildings'?'selected':'')+'>Building layer</option><option value="demand" '+(state.layer==='demand'?'selected':'')+'>Baseline energy</option></select></div><div class="map-stage"><svg id="village-map" class="village-map" viewBox="0 0 800 470" role="img" aria-label="Interactive map of Lamwo village boundaries and mini-grid sites"></svg><div class="map-badge"><span></span>'+(s.manual?'Manual coordinates · no local spatial coverage':(state.layer==='demand'?'Fixed baseline · 60% uptake, 20 kWh/household':'411 villages · observed site features'))+'</div><div class="map-controls"><button data-action="zoom-in" aria-label="Zoom in">'+icon('plus')+'</button><button data-action="zoom-out" aria-label="Zoom out">'+icon('minus')+'</button><button data-action="zoom-reset" aria-label="Reset map">'+icon('expand')+'</button></div><div class="compass"><span>N</span><svg viewBox="0 0 24 24"><path d="m12 2 6 18-6-4-6 4Z" fill="#829976"/><path d="m12 2 0 14-6 4Z" fill="#c5d3b9"/></svg></div><div class="map-legend"><span><i class="legend-dot" style="background:#436c49"></i>Existing mini-grid</span><span><i class="legend-dot" style="background:#b7d780;border:1px solid #6e924c"></i>Candidate</span><span><i class="legend-dot" style="background:#edbb6c"></i>Selected</span></div><div class="map-attribution">Lamwo reference data · geographic boundaries</div></div><div id="map-summary">'+mapSummary()+'</div></section><div id="insight">'+insightMarkup()+'</div></div><aside class="panel inspector" aria-label="Demand assumptions"><div class="panel-head"><div><h2>Shape the scenario</h2><p class="subtext">'+escapeHtml(s.name)+' · month 1</p></div>'+icon('sliders')+'</div><div class="inspector-status">Planning scenario · assumptions are editable</div><div class="inspector-tabs"><button class="'+(state.inspector==='assumptions'?'active':'')+'" data-action="inspector" data-tab="assumptions">Assumptions</button><button class="'+(state.inspector==='site'?'active':'')+'" data-action="inspector" data-tab="site">Site evidence</button></div><div class="assumptions-body" id="assumptions-body">'+inspectorMarkup()+'</div><div class="inspector-footer"><p>Low / base / high are scenario envelopes. Metered-site accuracy has not been established.</p><button class="btn" data-action="advanced">'+icon('sliders')+'All assumptions & growth</button></div></aside></div><div class="charts-row"><section class="panel"><div class="panel-head"><div><h2>A day in the life of this village</h2><p class="subtext">Average-day load profile · month 1</p></div><span class="head-tag">'+(ramp?'RAMP shapes':'Explicit profile shapes')+'</span></div><div class="chart-body" id="daily-chart">'+dailyChart()+'</div></section><section class="panel"><div class="panel-head"><div><h2>Plan beyond the first connection</h2><p class="subtext">Monthly energy · 24-month growth scenario</p></div><span class="head-tag">Low / base / high</span></div><div class="chart-body" id="growth-chart">'+growthChart()+'</div></section></div><div class="evidence-banner"><div><h3>Turn evidence gaps into a field assessment.</h3><p>Inspect each input, answer priority questions, and compare the revision.</p></div><button class="btn" data-action="nav" data-view="field">Open assessment '+icon('arrow')+'</button></div><div class="print-only">'+reportNotes()+'</div>';}
function mapSummary(){const s=site();return '<div class="map-summary"><div class="selected-location"><div class="pin-square">'+icon('pin')+'</div><div><strong>'+escapeHtml(s.name)+'</strong><p>'+escapeHtml(s.manual?'User-entered location':(s.parish||s.subcounty||'Lamwo')+' · Lamwo, Uganda')+'</p></div></div><span class="tag">'+statusLabel(s)+'</span></div><div class="site-facts"><div><span>Population estimate</span><strong>'+fmt(state.populationOverride??s.population)+' <small>people</small></strong></div><div><span>Observed buildings</span><strong>'+fmt(s.buildings)+' <small>structures</small></strong></div><div><span>Mapped public facilities</span><strong>'+fmt(Number(s.schools||0)+Number(s.clinics||0))+' <small>schools / clinics</small></strong></div></div>';}
function slider(key,label,min,max,step,suffix,help){const v=state.inputs[key];return '<div class="control"><label for="input-'+key+'">'+label+'<span class="value-badge">'+fmt(v,step<1?1:0)+suffix+'</span></label><input type="range" id="input-'+key+'" data-input="'+key+'" min="'+min+'" max="'+max+'" step="'+step+'" value="'+v+'"><div class="range-ends"><span>'+min+suffix+'</span><span>'+max+suffix+'</span></div>'+(help?'<p class="control-help">'+help+'</p>':'')+'</div>';}
function stepper(key,label,i){return '<div class="stepper-row"><span class="stepper-label">'+icon(i)+label+'</span><div class="stepper"><button data-action="step" data-key="'+key+'" data-delta="-1" aria-label="Remove '+label+'">−</button><span id="value-'+key+'">'+state.inputs[key]+'</span><button data-action="step" data-key="'+key+'" data-delta="1" aria-label="Add '+label+'">+</button></div></div>';}
function inspectorMarkup(){const s=site();if(state.inspector==='site')return '<div class="mini-facts"><div class="mini-fact"><span>Village ID</span><strong>'+escapeHtml(s.id)+'</strong></div><div class="mini-fact"><span>Source type</span><strong>'+(s.manual?'Manual':'Geospatial')+'</strong></div><div class="mini-fact"><span>Schools</span><strong>'+fmt(s.schools)+'</strong></div><div class="mini-fact"><span>Clinics</span><strong>'+fmt(s.clinics)+'</strong></div></div><div class="divider"></div><p class="info-note">'+(s.manual?'This site uses your entered population and facility counts. Automatic satellite extraction is not available outside the Lamwo pilot.':'Population and building counts come from the processed Lamwo feature table. Buildings are structures; households are estimated separately from population.')+'</p><div class="divider"></div><p class="control-title">Evidence limits</p><p class="control-help">'+escapeHtml(Array.isArray(s.data_flags)?s.data_flags.join(' · '):'Population and buildings are geospatial estimates. Zero-valued environmental features require a coverage check.')+'</p><p class="control-help">No measured site consumption is included.</p><div id="breakdown-inspector">'+breakdownMarkup()+'</div>';return slider('connectionPercent','Household connection uptake',0,100,1,'%','Share of potential households connected at launch.')+slider('householdKWhPerMonth','Energy per connected household',0,Math.max(100,Math.ceil(state.inputs.householdKWhPerMonth/10)*10),0.1,' kWh',state.mlSource?'AI survey-proxy estimate applied; inspect its scope in the model lab.':'Editable monthly assumption; default 20 kWh.')+'<button class="btn ghost" data-action="survey-anchor" style="font-size:9px;padding:3px 0;margin-top:-8px">Use rural survey reference · '+fmt(survey.groups.rural.weighted.p50)+' kWh ↗</button>'+'<div class="divider"></div><p class="control-title">Connected productive-use loads</p>'+stepper('millCount','Grain mills','mill')+stepper('refrigerationCount','Refrigeration units','fridge')+stepper('salonCount','Salons','salon')+stepper('weldingCount','Welding shops','welding')+'<p class="control-help">Business counts are scenario inputs, not satellite detections.</p><div id="breakdown-inspector">'+breakdownMarkup()+'</div>';}
function breakdownMarkup(){return '<div class="breakdown">'+result.breakdown.map(b=>'<div style="width:'+b.share*100+'%;background:'+colors[b.key]+'"></div>').join('')+'</div><div class="breakdown-list">'+result.breakdown.map(b=>'<div class="breakdown-item"><span><i class="legend-dot" style="background:'+colors[b.key]+'"></i>'+b.label+'</span><strong>'+fmt(b.monthlyKWh)+' kWh</strong></div>').join('')+'</div>';}
function insightMarkup(){const r=result,share=r.firstMonth.businessKWh/(r.firstMonth.totalKWh||1),b=state.inputs.millCount+state.inputs.refrigerationCount+state.inputs.salonCount+state.inputs.weldingCount;return '<div class="insight-strip">'+icon('leaf')+'<div><strong>'+(b?'Productive use contributes '+pct(share)+' of this energy scenario.':'What could a daytime business change?')+'</strong><p>'+(b?'Compare this scenario with one without business loads. Their operating hours shape the average-day peak and load factor.':'Add a grain mill or refrigeration unit to see how productive activity changes demand and the daily profile.')+'</p></div></div>';}
function chartAxes(maxY,xLabels,unit){let t='';for(let i=0;i<5;i++){const y=170-i*36;t+='<line class="gridline" x1="42" y1="'+y+'" x2="448" y2="'+y+'"/><text x="33" y="'+(y+3)+'" text-anchor="end">'+fmt(maxY*i/4,maxY<10?1:0)+'</text>';}xLabels.forEach(([x,label])=>{t+='<text x="'+x+'" y="191" text-anchor="middle">'+label+'</text>';});return t+'<text x="42" y="14">'+unit+'</text>';}
function linePath(values,maxY){return values.map((v,i)=>(i?'L':'M')+(42+i*406/(values.length-1)).toFixed(2)+','+(170-v/maxY*144).toFixed(2)).join(' ');}
function areaPath(low,high,maxY){const up=linePath(high,maxY),down=low.map((v,i)=>[42+i*406/(low.length-1),170-v/maxY*144]).reverse().map(([x,y])=>'L'+x.toFixed(2)+','+y.toFixed(2)).join(' ');return up+' '+down+' Z';}
function dailyChart(){const p=result.dailyProfile,maxY=Math.max(1,...p.map(x=>x.totalKW))*1.18,a=p.map(x=>x.householdKW),b=p.map(x=>x.householdKW+x.businessKW),c=p.map(x=>x.totalKW),zero=Array(24).fill(0);return '<div class="chart-summary"><span>Simulated daily energy <b>'+fmt(result.firstMonth.dailyKWh,1)+' kWh</b></span><span>30-day average</span></div><svg class="chart" viewBox="0 0 470 205" role="img" aria-label="Stacked hourly household, business and service demand chart">'+chartAxes(maxY,[[42,'00:00'],[148,'06:00'],[254,'12:00'],[360,'18:00'],[448,'23:00']],'kW')+'<path d="'+areaPath(zero,a,maxY)+'" fill="'+colors.household+'" opacity=".86"/><path d="'+areaPath(a,b,maxY)+'" fill="'+colors.business+'"/><path d="'+areaPath(b,c,maxY)+'" fill="'+colors.services+'"/><path d="'+linePath(c,maxY)+'" stroke="#2e5436" stroke-width="1.5" fill="none"/></svg><div class="chart-legend"><span class="legend-key"><i style="background:'+colors.household+'"></i>Households</span><span class="legend-key"><i style="background:'+colors.business+'"></i>Businesses</span><span class="legend-key"><i style="background:'+colors.services+'"></i>Public services</span></div><p class="chart-caption">'+(ramp?'RAMP-generated timing shapes, normalized to scenario energy.':'Explicit assumed timing shapes, normalized to scenario energy.')+' Average-day peaks are not equipment sizing or starting-surge estimates.</p>';}
function growthChart(){const lo=result.scenarios.low.monthly.map(x=>x.totalKWh),hi=result.scenarios.high.monthly.map(x=>x.totalKWh),base=result.monthly.map(x=>x.totalKWh),maxY=Math.max(1,...hi)*1.12;return '<div class="chart-summary"><span>Year 1 <b>'+fmt(result.year1.totalKWh/1000,1)+' MWh</b></span><span>Year 2 <b>'+fmt(result.year2.totalKWh/1000,1)+' MWh</b></span></div><svg class="chart" viewBox="0 0 470 205" role="img" aria-label="24-month demand growth with low and high scenario band">'+chartAxes(maxY,[[42,'Month 1'],[148,'6'],[254,'12'],[360,'18'],[448,'24']],'kWh / month')+'<path d="'+areaPath(lo,hi,maxY)+'" fill="#c4dca0" opacity=".38"/><path d="'+linePath(lo,maxY)+'" stroke="#bfd298" stroke-width="1" stroke-dasharray="3 4" fill="none"/><path d="'+linePath(hi,maxY)+'" stroke="#bfd298" stroke-width="1" stroke-dasharray="3 4" fill="none"/><path d="'+linePath(base,maxY)+'" stroke="#416944" stroke-width="2.7" fill="none"/><circle cx="448" cy="'+(170-base[23]/maxY*144)+'" r="4" fill="#416944" stroke="white" stroke-width="2"/></svg><div class="chart-legend"><span class="legend-key"><i style="background:#416944"></i>Base scenario</span><span class="legend-key"><i style="background:#c4dca0"></i>Low–high envelope</span></div><p class="chart-caption">Assumed uptake, appliance adoption and business growth. Envelopes are 0.70× / 1.35× base energy; they are not calibrated probability intervals.</p>';}
function refreshOutputs(){calculate();if($('#metrics'))$('#metrics').innerHTML=metricsMarkup();if($('#daily-chart'))$('#daily-chart').innerHTML=dailyChart();if($('#growth-chart'))$('#growth-chart').innerHTML=growthChart();if($('#insight'))$('#insight').innerHTML=insightMarkup();if($('#breakdown-inspector'))$('#breakdown-inspector').innerHTML=breakdownMarkup();if($('#map-summary'))$('#map-summary').innerHTML=mapSummary();persist();}
function getBounds(){if(site().manual){const x=Number(site().longitude),y=Number(site().latitude);return [x-.12,y-.08,x+.12,y+.08];}const coords=[];for(const f of boundaries.features){const collect=a=>{if(typeof a[0]==='number')coords.push(a);else a.forEach(collect);};collect(f.geometry.coordinates);}return [Math.min(...coords.map(p=>p[0])),Math.min(...coords.map(p=>p[1])),Math.max(...coords.map(p=>p[0])),Math.max(...coords.map(p=>p[1]))];}
function projectPoint(p){const [x0,y0,x1,y1]=mapBounds,scale=Math.min(690/(x1-x0),375/(y1-y0));return [400+(p[0]-(x0+x1)/2)*scale,245-(p[1]-(y0+y1)/2)*scale];}
function polygonPath(geom){const rings=geom.type==='Polygon'?geom.coordinates:geom.type==='MultiPolygon'?geom.coordinates.flat():[];return rings.map(r=>r.map((p,i)=>{const [x,y]=projectPoint(p);return (i?'L':'M')+x.toFixed(1)+','+y.toFixed(1);}).join(' ')+'Z').join(' ');}
function layerValue(s){if(state.layer==='buildings')return Number(s.buildings)||0;if(state.layer==='demand')return (Number(s.population)||0)/4.5*.6*20+Number(s.schools||0)*3*30+Number(s.clinics||0)*5*30;return Number(s.population)||0;}
function drawMap(){const svg=$('#village-map');if(!svg)return;mapBounds=getBounds();const badge=$('.map-badge');if(badge)badge.innerHTML='<span></span>'+(site().manual?'Manual coordinates · no local spatial coverage':state.layer==='demand'?'Fixed baseline · 60% uptake, 20 kWh/household':'411 villages · observed site features');let bg='<defs><pattern id="map-grid" width="48" height="48" patternUnits="userSpaceOnUse"><path d="M48 0H0V48" fill="none" stroke="#dce5d0" stroke-width=".5"/></pattern><radialGradient id="map-bg"><stop offset="0%" stop-color="#f5f7ed"/><stop offset="100%" stop-color="#e7eddc"/></radialGradient></defs><rect width="800" height="470" fill="url(#map-bg)"/><rect width="800" height="470" fill="url(#map-grid)"/>';let polygons='',points='',labels='';const maxV=Math.max(1,...sites.filter(s=>!s.manual).map(layerValue));if(!site().manual){for(const f of boundaries.features){const id=f.id??f.properties.id??f.properties.village_id;const s=sites.find(x=>String(x.id)===String(id));if(!s)continue;const intensity=Math.sqrt(layerValue(s)/maxV),light=91-intensity*28;polygons+='<path data-site="'+escapeHtml(id)+'" class="map-poly '+(String(id)===String(state.siteId)?'selected':'')+'" d="'+polygonPath(f.geometry)+'" fill="hsl(87 28% '+light+'%)"><title>'+escapeHtml(s.name)+' · '+fmt(s.population)+' people · '+fmt(s.buildings)+' buildings</title></path>';}}
for(const s of sites){if(site().manual&&s.id!==site().id)continue;if(!Number.isFinite(Number(s.latitude))||!Number.isFinite(Number(s.longitude)))continue;const [x,y]=projectPoint([Number(s.longitude),Number(s.latitude)]);const selected=String(s.id)===String(state.siteId);if(selected||s.candidate||s.existing){points+='<g class="map-point" data-site="'+escapeHtml(s.id)+'">'+(selected?'<circle cx="'+x+'" cy="'+y+'" r="14" fill="#d5a55130"/><circle cx="'+x+'" cy="'+y+'" r="8" fill="#edbb6c" stroke="#fff" stroke-width="2.5"/>':'<circle cx="'+x+'" cy="'+y+'" r="'+(s.existing?4.5:4)+'" fill="'+(s.existing?'#436c49':'#c3df8f')+'" stroke="'+(s.existing?'#fff':'#749354')+'" stroke-width="1.2"/>')+'<title>'+escapeHtml(s.name)+' · '+statusLabel(s)+'</title></g>';if(selected||s.existing&&Number(s.population)>1000)labels+='<text class="map-label" x="'+(x+10)+'" y="'+(y-8)+'">'+escapeHtml(s.name)+'</text>';}}
const manual=site().manual;svg.innerHTML=bg+'<g id="map-viewport">'+polygons+'<text class="map-context" x="'+(manual?220:90)+'" y="430">'+(manual?'MANUAL SITE · '+fmt(site().latitude,3)+'°, '+fmt(site().longitude,3)+'°':'LAMWO · NORTHERN UGANDA')+'</text>'+points+labels+'</g>';updateMapTransform();let drag=null;svg.onpointerdown=e=>{if(e.button!==0)return;drag={x:e.clientX,y:e.clientY,px:state.panX,py:state.panY,moved:false};svg.setPointerCapture(e.pointerId);};svg.onpointermove=e=>{if(!drag)return;const dx=(e.clientX-drag.x)*800/svg.clientWidth,dy=(e.clientY-drag.y)*470/svg.clientHeight;if(Math.abs(dx)+Math.abs(dy)>5)drag.moved=true;if(drag.moved){state.panX=drag.px+dx;state.panY=drag.py+dy;updateMapTransform();}};svg.onpointerup=e=>{const wasDrag=drag?.moved;drag=null;if(!wasDrag){const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-site]');if(target)selectSite(target.dataset.site);}};}
function updateMapTransform(){const v=$('#map-viewport');if(v)v.setAttribute('transform','translate('+state.panX+' '+state.panY+') translate(400 235) scale('+state.zoom+') translate(-400 -235)');}
function bindSearch(){const input=$('#village-search'),box=$('#search-results');if(!input)return;input.addEventListener('input',()=>{const q=input.value.toLowerCase().trim();if(!q){box.hidden=true;return;}const matches=sites.filter(s=>(s.name+' '+s.parish+' '+s.subcounty+' '+s.id).toLowerCase().includes(q)).slice(0,12);box.innerHTML=matches.length?matches.map(s=>'<button data-action="select-site" data-id="'+escapeHtml(s.id)+'"><span>'+escapeHtml(s.name)+'</span><small>'+statusLabel(s)+'</small></button>').join(''):'<div class="empty" style="padding:15px">No matching village. Use Village explorer to add a manual site.</div>';box.hidden=false;});input.addEventListener('keydown',e=>{if(e.key==='Escape')box.hidden=true;if(e.key==='Enter'){const first=$('button',box);if(first)selectSite(first.dataset.id);}});}
function directoryView(){const q=state.directoryQuery.toLowerCase(),filtered=sites.filter(s=>(state.directoryFilter==='all'||state.directoryFilter==='candidate'&&s.candidate||state.directoryFilter==='existing'&&s.existing||state.directoryFilter==='manual'&&s.manual)&&(s.name+' '+s.parish+' '+s.subcounty).toLowerCase().includes(q));return '<div class="view-heading"><h2>Find the next community to power.</h2><p>Explore observed Lamwo village features, or create a manual scenario for another location.</p></div><div class="directory-controls"><input id="directory-search" aria-label="Filter village directory" placeholder="Search by village, parish or subcounty" value="'+escapeHtml(state.directoryQuery)+'"><select id="directory-filter" aria-label="Filter site type"><option value="all">All villages</option><option value="candidate" '+(state.directoryFilter==='candidate'?'selected':'')+'>39 candidate sites</option><option value="existing" '+(state.directoryFilter==='existing'?'selected':'')+'>24 existing-site villages</option><option value="manual" '+(state.directoryFilter==='manual'?'selected':'')+'>Manual sites</option></select><button class="btn primary" data-action="new-site">'+icon('plus')+'Add manual site</button><span class="pill-text">'+filtered.length+' locations</span></div><div class="site-directory">'+filtered.slice(0,90).map(s=>'<button class="panel directory-card" data-action="select-site" data-id="'+escapeHtml(s.id)+'"><span class="tag">'+statusLabel(s)+'</span><h3>'+escapeHtml(s.name)+'</h3><p>'+escapeHtml(s.parish||s.subcounty||'Manual location')+'</p><div class="directory-stats"><div><strong>'+fmt(s.population)+'</strong>people</div><div><strong>'+fmt(s.buildings)+'</strong>buildings</div><div><strong>'+fmt(Number(s.schools||0)+Number(s.clinics||0))+'</strong>public facilities</div></div></button>').join('')+'</div>'+(filtered.length>90?'<p class="subtext" style="margin-top:15px">Showing the first 90 matches. Search to narrow the directory.</p>':'')+(!filtered.length?'<div class="panel empty">No locations match this filter.</div>':'');}
function scenariosView(){return '<div class="view-heading"><h2>Make the trade-offs visible.</h2><p>Save a baseline, add a business, and compare the consequences. Scenarios stay in this browser.</p></div><section class="panel">'+(saved.length?'<div class="panel-head"><h2>'+saved.length+' saved scenarios</h2><button class="btn" data-action="save">'+icon('plus')+'Save current</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Scenario / village</th><th>Month 1 energy</th><th>Average-day peak</th><th>Load factor</th><th>Month 24 energy</th><th>Actions</th></tr></thead><tbody>'+saved.map((item,i)=>{const s=sites.find(x=>String(x.id)===String(item.siteId));if(!s)return '';const r=calculateDemand({...s,population:item.populationOverride??s.population},item.inputs,templates);return '<tr><td><strong>'+escapeHtml(item.name)+'</strong><p class="subtext">'+escapeHtml(s.name)+'</p></td><td>'+fmt(r.firstMonth.totalKWh)+' kWh</td><td>'+fmt(r.firstMonth.peakKW,1)+' kW</td><td>'+pct(r.firstMonth.loadFactor)+'</td><td>'+fmt(r.monthly[23].totalKWh)+' kWh</td><td><button class="btn" data-action="load-scenario" data-index="'+i+'">Open</button> <button class="btn ghost" data-action="delete-scenario" data-index="'+i+'" aria-label="Delete '+escapeHtml(item.name)+'">×</button></td></tr>';}).join('')+'</tbody></table></div>':'<div class="empty"><h3>Your next decision deserves a comparison.</h3><p>Save a village’s baseline, add productive-use loads, then save a second scenario.</p><button class="btn primary" data-action="nav" data-view="overview" style="margin-top:20px">Build your first scenario '+icon('arrow')+'</button></div>')+'</section><div class="info-note" style="margin-top:20px">Energy, peak and load factor describe an assumed average day. Compare like-for-like assumptions; these calculations do not establish project viability, equipment sizes or forecast accuracy.</div>';}
function sourceRow(title,tag,text,url,label){return '<div class="source-row"><div><h3>'+title+'</h3><span class="tag">'+tag+'</span></div><p>'+text+'</p>'+(url?'<a href="'+url+'" target="_blank" rel="noopener noreferrer">'+label+' ↗</a>':'<span></span>')+'</div>';}
function evidenceView(){const count=survey?.quality?.unique_households??445;return '<div class="view-heading"><h2>Trust begins with traceable evidence.</h2><p>Here is what we observed, what we assumed, and what still needs to be measured.</p></div><div class="evidence-grid"><section class="panel evidence-card"><div class="number">411</div><h3>Villages with real geographic inputs</h3><p>Population, buildings, schools and clinics come from the Lamwo feature table. Candidate and existing labels use the curated 39 / 25 site tables.</p></section><section class="panel evidence-card"><div class="number">'+count+'</div><h3>Unique survey households</h3><p>The 28,625 source rows repeat household IDs. Only stable household fields are summarized. Electricity use is inferred from payments at an assumed UGX 250/kWh.</p></section><section class="panel evidence-card"><div class="number">0</div><h3>Direct-meter site validation tests</h3><p>Metered evidence includes a separate DRC kWh-purchase benchmark and Tanzania current readings; direct-meter village accuracy and interval coverage remain unverified. Low / base / high are transparent scenarios. Synthetic RAMP outputs are not independent validation.</p></section></div><div class="info-note" style="margin-top:20px"><strong>New metered-data diagnostic:</strong> open Metered evidence for 40,809 acquired Tanzania current readings and four later-day timing comparisons. This does not validate village kWh predictions.<br><br><strong>Trained AI now available:</strong> open AI model lab for the household random forest, baseline comparison, split-conformal evaluation, geographic archetypes and model limitations. These are household survey tests, not metered-site validation.</div><div class="equation">Site energy = <strong>connected households × energy per household</strong> + <strong>business loads</strong> + <strong>public services</strong></div><div class="method-steps"><section class="panel method-step"><b>01 / OBSERVE</b><h3>Describe the settlement</h3><p>Join real village names, coordinates and geographic boundaries with population and building features.</p></section><section class="panel method-step"><b>02 / MAKE ASSUMPTIONS</b><h3>Define connected users</h3><p>Choose household uptake, energy use, business equipment, facilities and growth. Every assumption can be edited.</p></section><section class="panel method-step"><b>03 / SIMULATE</b><h3>Build the daily profile</h3><p>'+(ramp?'Use cached RAMP timing shapes from '+escapeHtml(ramp.provenance?.runs??30)+' seeded simulation days. Normalize them to the scenario’s energy.':'Use explicit normalized hourly shapes. No black-box accuracy claim is made.')+'</p></section><section class="panel method-step"><b>04 / EXPLAIN</b><h3>Compare the next 24 months</h3><p>Show contributions, growth assumptions and 0.70× / 1.35× envelopes. Export the assumptions alongside the results.</p></section></div><section class="panel source-list"><div class="panel-head"><h2>Source register</h2><button class="btn" data-action="audit-download">'+icon('download')+'Download source audit</button></div>'+sourceRow('Lamwo feature data','Observed · spatial estimates','411 village records. Names and centers joined by exact ID. Historical layer dates vary. Zero NDVI and wind values in 366 villages need coverage checks; these fields are excluded from demand calculations.','./data/catalog.json','Source audit')+sourceRow('Household survey','Context only · 2019/2020','445 unique households: 91 rural, 354 urban. No Lamwo household sample was identified. Household size varies within 421 IDs and is excluded. The default 20 kWh/month is an editable scenario assumption, not a fitted mini-grid prediction.','https://data.mendeley.com/datasets/h5cc2cfy26/2','Dataset description')+sourceRow('Load profile shapes',ramp?'RAMP · synthetic':'Explicit profile assumptions',ramp?'Seven appliance categories generated with RAMP '+escapeHtml(ramp.provenance?.version||'')+'. Seed and appliance assumptions are included in the downloadable source audit. Shapes represent timing; energy levels come from editable assumptions.':'The runtime uses documented assumed timing shapes. Synthetic profiles must never be presented as observed consumption.','https://github.com/RAMP-project/RAMP','RAMP source')+sourceRow('Satellite-derived layers','Existing Lamwo inputs','The pilot uses the building and population features supplied in the reference project. No live satellite-image analysis is performed by this app. Satellite & drone adds a dated 2024 pilot mosaic and local survey/history imports. No annual village-count series has been acquired, and imagery does not measure electricity use.','https://sites.research.google/gr/open-buildings/','Open Buildings')+'</section><section class="panel source-list"><div class="panel-head"><h2>Readiness against the challenge</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Requirement</th><th>Current demonstration</th><th>Status</th></tr></thead><tbody><tr><td>Demand estimate with a range</td><td>Explainable energy scenarios and explicit low / high multipliers</td><td>Implemented · uncalibrated</td></tr><tr><td>Growth after connection</td><td>24-month assumed uptake, appliance and business growth</td><td>Implemented · scenario only</td></tr><tr><td>Held-out metered validation</td><td>Tanzania current-shape diagnostic available; no matched unseen-site kWh test</td><td>Unmet</td></tr><tr><td>Explainability</td><td>Category breakdown, inputs, source audit and downloadable report</td><td>Implemented</td></tr><tr><td>Any location</td><td>411 automatic Lamwo records; manual inputs elsewhere</td><td>Partial · coverage explicit</td></tr><tr><td>Safe operator data sharing</td><td>Proposed schema and sharing safeguards in project documentation</td><td>Proposal</td></tr></tbody></table></div></section><div class="validation-note"><strong>Engineering limit:</strong> The displayed peak comes from an average-day profile. Motor starting surges, operating-day peaks, seasonality, distribution losses, reliability and battery behavior require a separate engineering assessment. This app does not prescribe system size.</div>';}
function pitchView(){return '<div class="info-note" style="margin-bottom:18px"><strong>New AI demonstration:</strong> visit AI model lab to show the trained model and evaluation ledger. The forest achieved 44.14 kWh/month household-proxy MAE versus 49.09 for the median benchmark on 89 held-out households; measured mini-grid accuracy remains unverified.</div><section class="pitch-hero"><div class="eyebrow">THE AIMENERGY STORY</div><h2>Before we build the grid,<br>understand the village.</h2><p>A developer faces a costly decision with little data. AimEnergy turns open geographic evidence and visible assumptions into a demand scenario they can question, change and explain.</p><button class="btn lime" data-action="demo-start">'+icon('play')+'Start the demo journey</button></section><div class="pitch-grid"><section class="panel pitch-step"><div class="step-count">01 / THE COMMUNITY</div><h3>Start with a real place.</h3><p>Select a Lamwo village. Show population, building counts and public facilities. Explain the difference between an observed site feature and a demand assumption.</p></section><section class="panel pitch-step"><div class="step-count">02 / THE DECISION</div><h3>Give productive use a role.</h3><p>Save a household baseline. Add a grain mill or refrigeration load. Let the audience see how the energy mix, daily profile and load factor change.</p></section><section class="panel pitch-step"><div class="step-count">03 / THE FUTURE</div><h3>Know what to verify next.</h3><p>Inspect the evidence passport, answer sensitivity-ranked field questions, and compare the revised scenario. Prepare the device for offline assessment before travelling.</p></section></div><div class="evidence-banner"><div><h3>The claim we can defend</h3><p>A working, reproducible planning prototype using 411 real villages, open-source load simulation and transparent demand assumptions.</p></div><button class="btn" data-action="nav" data-view="evidence">See the evidence '+icon('arrow')+'</button></div>';}
function showModal(title,body,actions='',large=false){document.querySelector('.modal-backdrop')?.remove();const el=document.createElement('div');el.className='modal-backdrop';el.innerHTML='<section class="modal '+(large?'large':'')+'" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">'+title+'</h2><button class="close-btn" data-action="close-modal" aria-label="Close dialog">×</button></div>'+body+(actions?'<div class="modal-actions">'+actions+'</div>':'')+'</section>';document.body.append(el);el.addEventListener('click',e=>{if(e.target===el)el.remove();});setTimeout(()=>$('input,button',el)?.focus(),0);}
function reportNotes(){return (state.fieldEvidence?'<strong>Assessment history:</strong> '+escapeHtml(state.fieldEvidence.id)+'. Responses are user-declared and separate from the original source; later scenario edits may supersede them.<br>':'')+(state.mlSource?'<strong>AI input:</strong> household energy comes from survey-proxy model '+escapeHtml(state.mlSource.model_id)+'. Its household residual interval does not apply to village totals. The held-out survey showed systematic underprediction.<br>':'')+'<strong>Evidence:</strong> Lamwo geographic inputs; household survey contextual only; '+(ramp?'RAMP-generated synthetic timing shapes':'explicit timing assumptions')+'.<br><strong>Model:</strong> '+escapeHtml(result.modelType)+'.<br><strong>Limit:</strong> Low / base / high are uncalibrated assumption envelopes. Metered accuracy and interval coverage are unverified. Average-day peaks do not prescribe equipment sizes.';}
function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}
function exportData(){return {project:'AimEnergy',generatedAt:new Date().toISOString(),site:siteForModel(),inputs:state.inputs,model:result.modelType,fieldAssessment:state.fieldEvidence||null,evidencePassport:buildPassport({site:siteForModel(),sourceSite:site(),inputs:state.inputs,mlSource:state.mlSource,fieldEvidence:state.fieldEvidence,mlSchema:getMLEvidence().feature_schema,profileProvenance:ramp?.provenance}),mlEvidence:state.mlSource?{...state.mlSource,evaluation:getMLEvidence().evaluation}:null,profileProvenance:ramp?.provenance??{engine:'Explicit assumed profiles'},evidenceStatus:'Uncalibrated scenario; no held-out metered validation',scenarios:result.scenarios,assumptions:result.assumptions,surveyContext:survey};}
function exportReport(){const r=result,s=site(),i=state.inputs;const rows=r.monthly.map((m,n)=>'<tr><td>'+m.month+'</td><td>'+fmt(m.connections,1)+'</td><td>'+fmt(r.scenarios.low.monthly[n].totalKWh,1)+'</td><td>'+fmt(m.totalKWh,1)+'</td><td>'+fmt(r.scenarios.high.monthly[n].totalKWh,1)+'</td><td>'+fmt(m.peakKW,2)+'</td></tr>').join('');const html='<!doctype html><html><head><meta charset="utf-8"><title>AimEnergy — '+escapeHtml(s.name)+' planning report</title><style>body{max-width:1000px;margin:40px auto;padding:20px;font:14px/1.7 Arial;color:#173b2d}h1{font-size:30px}h2{margin-top:32px;font-size:20px}table{border-collapse:collapse;width:100%;font-size:12px}th,td{padding:8px;border-bottom:1px solid #ddd;text-align:left}th{background:#eff5e7}.note{background:#f0f5e9;padding:16px;border-radius:8px}button{padding:10px 20px;margin:15px 0;background:#244f41;color:white;border:0;border-radius:6px}@media print{button{display:none}body{margin:0}}</style></head><body><h1>AimEnergy · Village planning report</h1><p>'+escapeHtml(s.name)+' · '+escapeHtml(s.parish||'Manual site')+' · '+escapeHtml(s.manual?'User-entered location':'Lamwo, Uganda')+'</p><p>Generated '+escapeHtml(new Date().toISOString())+'</p><div class="note">'+reportNotes()+'</div><button onclick="window.print()">Print / Save as PDF</button><h2>Month 1 base scenario</h2><p><strong>'+fmt(r.firstMonth.totalKWh)+' kWh/month</strong> · '+fmt(r.firstMonth.connections)+' household connection equivalents · '+fmt(r.firstMonth.peakKW,1)+' kW average-day peak · '+pct(r.firstMonth.loadFactor)+' load factor.</p><h2>Observed site inputs</h2><p>Population: '+fmt(state.populationOverride??s.population)+' people'+(state.populationOverride!=null?' (user override)':'')+'. Buildings: '+fmt(s.buildings)+'. Mapped schools: '+fmt(s.schools)+'. Mapped clinics: '+fmt(s.clinics)+'.</p><h2>All editable assumptions</h2><table><tr><th>Input</th><th>Value</th></tr>'+Object.entries(i).map(([k,v])=>'<tr><td>'+escapeHtml(k)+'</td><td>'+escapeHtml(v)+'</td></tr>').join('')+'</table><h2>24-month energy scenarios</h2><table><tr><th>Month</th><th>Connections</th><th>Low kWh</th><th>Base kWh</th><th>High kWh</th><th>Base peak kW</th></tr>'+rows+'</table><h2>Assumptions and limitations</h2><ul>'+r.assumptions.map(a=>'<li>'+escapeHtml(a)+'</li>').join('')+'</ul>'+(state.mlSource?'<h2>AI household profile</h2><p>Model: '+escapeHtml(state.mlSource.model_id)+'. Applied as a scenario input; historical household intervals do not calibrate village totals.</p><table><tr><th>Feature</th><th>Scenario value</th></tr>'+Object.entries(state.mlSource.features||{}).map(([key,value])=>{const spec=getMLEvidence().feature_schema?.find(f=>f.name===key);const label=spec?.options?.find(o=>Number(o.value)===Number(value))?.label??value;return '<tr><td>'+escapeHtml(spec?.label||key)+'</td><td>'+escapeHtml(label)+'</td></tr>';}).join('')+'</table>':'')+'<h2>Source provenance</h2><p>Lamwo feature table:411 villages; curated candidate39/existing25. Household survey:445unique IDs from2019/2020, payment-derived consumption; not site meter readings. Survey household size is excluded.</p><p>'+escapeHtml(JSON.stringify(ramp?.provenance||{engine:'Explicit assumed profiles'}))+'</p><p>Source register and methodology are included in the AimEnergy application and source package. No financial return or equipment sizing claim is made.</p></body></html>';download('AimEnergy-'+s.name.replace(/[^a-z0-9]/gi,'-')+'-report.html',html,'text/html;charset=utf-8');toast('Planning report downloaded. Open it to print or save as PDF.');}
function advancedModal(){const sections=[['Households & growth',[['peoplePerHousehold','People per household',1,20,.1],['connectionGrowthPercent','Connection growth by month 24 (%)',0,500,1],['applianceGrowthPercent','Household energy growth by month 24 (%)',0,500,1],['productiveUseGrowthPercent','Business energy growth by month 24 (%)',0,500,1]]],['Public services',[['schoolCount','Connected schools',0,100000,1],['schoolKWhPerDay','kWh per school / day',0,10000,.1],['clinicCount','Connected clinics',0,100000,1],['clinicKWhPerDay','kWh per clinic / day',0,10000,.1]]]];for(const [prefix,label] of [['mill','Grain mill'],['refrigeration','Refrigeration'],['salon','Salon'],['welding','Welding']])sections.push([label,[ [prefix+'PowerKW','Average running power (kW)',0,1000,.05],[prefix+'HoursPerDay','Equivalent full-power hours / operating day',0,24,.5],[prefix+'DaysPerMonth','Operating days per 30-day month',0,30,1] ]]);showModal('All assumptions & growth','<p>Changes update your scenario immediately. Growth percentages are relative changes from month 1 to month 24; uptake is capped at 100%.</p><div class="assumption-row"><label for="population-override">Population override (people)</label><input id="population-override" type="number" min="0" max="1000000000" step="1" value="'+(state.populationOverride??site().population)+'"></div>'+sections.map(([title,fields])=>'<div class="divider"></div><p class="control-title">'+title+'</p>'+fields.map(([key,label,min,max,step])=>'<div class="assumption-row"><label for="advanced-'+key+'">'+label+'</label><input id="advanced-'+key+'" data-input="'+key+'" type="number" min="'+min+'" max="'+max+'" step="'+step+'" value="'+state.inputs[key]+'"></div>').join('')).join('')+'<div class="validation-note">Power and hours define energy; the cached timing template remains fixed. The displayed peak is an average-day estimate. Motor surge and individual operating-day peaks need separate engineering work.</div>','<button class="btn" data-action="reset-inputs">Reset to site defaults</button><button class="btn primary" data-action="close-modal">Done</button>');}
function saveModal(){showModal('Save this planning scenario','<p>'+escapeHtml(site().name)+' · '+fmt(result.firstMonth.totalKWh)+' kWh/month · '+fmt(result.firstMonth.peakKW,1)+' kW average-day peak</p><div class="field"><label for="scenario-name">Scenario name</label><input id="scenario-name" maxlength="80" value="'+escapeHtml(site().name+' · '+(state.inputs.millCount?'with productive use':'baseline'))+'"></div>','<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="confirm-save">Save scenario</button>');}
function newSiteModal(){showModal('Plan a manual location','<p>Enter site observations or estimates for any location. This mode does not automatically retrieve satellite features.</p>'+[['new-name','Location name','text',''],['new-lat','Latitude (−90 to 90)','number','2.8'],['new-lon','Longitude (−180 to 180)','number','32.8'],['new-pop','Population estimate (people)','number','500'],['new-buildings','Building count (structures)','number','100'],['new-schools','Schools','number','1'],['new-clinics','Clinics','number','0']].map(([id,label,type,value])=>'<div class="field"><label for="'+id+'">'+label+'</label><input id="'+id+'" type="'+type+'" value="'+value+'" '+(type==='number'?'step="any"':'maxlength="80"')+' required></div>').join('')+'<p id="manual-error" role="alert" style="color:#a45236"></p>','<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="confirm-site">Create scenario</button>');}
function handleAction(action,target){if(action==='nav'){state.view=target.dataset.view;render();window.scrollTo({top:0,behavior:'smooth'});}if(action==='select-site')selectSite(target.dataset.id);if(action==='dismiss'){state.onboarding=false;$('.onboarding')?.remove();}if(action==='inspector'){state.inspector=target.dataset.tab;render();}if(action==='step'){const key=target.dataset.key;state.inputs[key]=Math.max(0,Math.min(100000,Number(state.inputs[key])+Number(target.dataset.delta)));$('#value-'+key).textContent=state.inputs[key];refreshOutputs();}if(action==='zoom-in'){state.zoom=Math.min(5,state.zoom*1.3);updateMapTransform();}if(action==='zoom-out'){state.zoom=Math.max(.7,state.zoom/1.3);updateMapTransform();}if(action==='zoom-reset'){state.zoom=1;state.panX=0;state.panY=0;updateMapTransform();}if(action==='advanced')advancedModal();if(action==='survey-anchor'){state.mlSource=null;state.inputs.householdKWhPerMonth=survey.groups.rural.weighted.p50;refreshOutputs();if($('#assumptions-body'))$('#assumptions-body').innerHTML=inspectorMarkup();toast('Applied rural survey expenditure proxy. This is not a metered mini-grid reference.');}if(action==='save')saveModal();if(action==='close-modal'){$('.modal-backdrop')?.remove();if(state.view==='overview')$('#assumptions-body').innerHTML=inspectorMarkup();}if(action==='confirm-save'){const name=$('#scenario-name').value.trim();if(!name){$('#scenario-name').focus();return;}saved.unshift({name,siteId:state.siteId,inputs:{...state.inputs},populationOverride:state.populationOverride,mlSource:state.mlSource,fieldEvidence:state.fieldEvidence,savedAt:new Date().toISOString()});saved=saved.slice(0,20);try{localStorage.setItem('aimenergy.scenarios',JSON.stringify(saved));}catch{toast('Browser storage is unavailable. Export a report to keep your scenario.');return;}$('.modal-backdrop')?.remove();toast('Scenario saved. Compare it in Saved scenarios.');if(state.view==='scenarios')render();}if(action==='load-scenario'){const item=saved[Number(target.dataset.index)];if(!item)return;state.siteId=item.siteId;state.inputs={...item.inputs};state.populationOverride=item.populationOverride;state.mlSource=item.mlSource;state.fieldEvidence=item.fieldEvidence;state.view='overview';state.zoom=1;state.panX=0;state.panY=0;persist();render();toast('Saved scenario loaded.');}if(action==='delete-scenario'){saved.splice(Number(target.dataset.index),1);try{localStorage.setItem('aimenergy.scenarios',JSON.stringify(saved));}catch{}render();}if(action==='export')showModal('Take the evidence with you','<p>Export the current '+escapeHtml(site().name)+' scenario with its inputs, assumptions, 24-month results and evidence limitations.</p><div class="divider"></div><p>The HTML report opens in your browser and supports Print / Save as PDF. CSV contains the 24 monthly scenarios; JSON contains the complete calculation and provenance.</p>','<button class="btn" data-action="export-csv">Monthly CSV</button><button class="btn" data-action="export-json">Full JSON</button><button class="btn primary" data-action="export-html">'+icon('download')+'Planning report</button>');if(action==='export-html')exportReport();if(action==='export-json'){download('AimEnergy-scenario.json',JSON.stringify(exportData(),null,2),'application/json');toast('Scenario and assumptions exported.');}if(action==='export-csv'){let csv='month,connections,low_kWh,base_kWh,high_kWh,base_average_day_peak_kW,base_load_factor,household_kWh,business_kWh,services_kWh\n';result.monthly.forEach((m,n)=>{csv+=[m.month,m.connections,result.scenarios.low.monthly[n].totalKWh,m.totalKWh,result.scenarios.high.monthly[n].totalKWh,m.peakKW,m.loadFactor,m.householdKWh,m.businessKWh,m.servicesKWh].join(',')+'\n';});download('AimEnergy-monthly-scenarios.csv',csv,'text/csv');toast('24-month scenario CSV exported.');}if(action==='audit-download'){download('AimEnergy-source-audit.json',JSON.stringify({catalog,survey,profileProvenance:ramp,modelAssumptions:result.assumptions},null,2),'application/json');toast('Source audit exported.');}if(action==='reset-inputs'){state.mlSource=null;state.inputs=defaultInputs(site(),survey);state.populationOverride=null;refreshOutputs();$('.modal-backdrop')?.remove();render();toast('Site defaults restored.');}if(action==='new-site')newSiteModal();if(action==='confirm-site'){if(['new-lat','new-lon','new-pop','new-buildings','new-schools','new-clinics'].some(id=>!$('#'+id).value.trim())){$('#manual-error').textContent='Complete every numeric field; enter 0 explicitly when a count is zero.';return;}const name=$('#new-name').value.trim(),lat=Number($('#new-lat').value),lon=Number($('#new-lon').value),pop=Number($('#new-pop').value),buildings=Number($('#new-buildings').value),schools=Number($('#new-schools').value),clinics=Number($('#new-clinics').value);if(!name||!Number.isFinite(lat)||Math.abs(lat)>90||!Number.isFinite(lon)||Math.abs(lon)>180||[pop,buildings,schools,clinics].some(v=>!Number.isFinite(v)||v<0||v>1e9)||[buildings,schools,clinics].some(v=>!Number.isInteger(v))||schools>100000||clinics>100000){$('#manual-error').textContent='Enter a name, valid coordinates, nonnegative population, and whole-number structure/facility counts (facilities ≤100,000).';return;}const item={id:'manual-'+Date.now(),name,latitude:lat,longitude:lon,population:pop,buildings,schools,clinics,manual:true,candidate:false,existing:false,data_flags:['User-entered observations; no automatic spatial retrieval']};customSites.push(item);sites.push(item);try{localStorage.setItem('aimenergy.custom',JSON.stringify(customSites));}catch{}$('.modal-backdrop')?.remove();selectSite(item.id);toast('Manual site created with your supplied observations.');}if(action==='demo-start'){const candidate=sites.filter(s=>s.candidate&&s.population>500&&s.population<2500&&s.buildings>0&&s.population/s.buildings>1.5&&s.population/s.buildings<10).sort((a,b)=>(b.schools+b.clinics)-(a.schools+a.clinics))[0]||sites[0];selectSite(candidate.id);toast('Demo: save this baseline, then add one grain mill.');}}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(target)handleAction(target.dataset.action,target);if(!e.target.closest('.search-wrap')){const box=$('#search-results');if(box)box.hidden=true;}});
document.addEventListener('input',e=>{const target=e.target;if(target.dataset.input){const key=target.dataset.input,value=Number(target.value);if(key==='householdKWhPerMonth')state.mlSource=null;if(target.value===''||!Number.isFinite(value))return;state.inputs[key]=value;const badge=target.closest('.control')?.querySelector('.value-badge');if(badge)badge.textContent=fmt(value,key==='householdKWhPerMonth'?1:0)+(key==='connectionPercent'?'%':' kWh');refreshOutputs();}if(target.id==='population-override'){if(target.value!==''&&Number.isFinite(Number(target.value))&&Number(target.value)>=0){state.populationOverride=Math.min(1e9,Number(target.value));refreshOutputs();}}if(target.id==='directory-search'){const pos=target.selectionStart;state.directoryQuery=target.value;$('#view-content').innerHTML=directoryView();const next=$('#directory-search');next.focus();next.setSelectionRange(pos,pos);}});
document.addEventListener('change',e=>{if(e.target.dataset.input){const key=e.target.dataset.input,raw=e.target.value;const clean=state.inputs[key];e.target.value=clean;if(raw===''||Number(raw)!==clean)toast('Input adjusted to the allowed planning range: '+clean+'.');}if(e.target.id==='population-override')e.target.value=state.populationOverride??site().population;if(e.target.id==='map-layer'){state.layer=e.target.value;drawMap();}if(e.target.id==='directory-filter'){state.directoryFilter=e.target.value;$('#view-content').innerHTML=directoryView();}});
document.addEventListener('keydown',e=>{const modal=$('.modal-backdrop');if(e.key==='Escape'){modal?.remove();if(state.view==='overview'&&$('#assumptions-body'))$('#assumptions-body').innerHTML=inspectorMarkup();$('#search-results')?.setAttribute('hidden','');}if(e.key==='Tab'&&modal){const list=$$('button,input,select,a[href]',modal).filter(x=>!x.disabled);const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
async function boot(){const read=async p=>{const r=await fetch('./data/'+p);if(!r.ok)throw new Error(p+' could not be loaded');return r.json();};try{const [siteData,geo,sur,cat,ram,metered,remote,drc,solar]=await Promise.all([read('sites.json'),read('boundaries.geojson'),read('survey-summary.json'),read('catalog.json'),read('ramp-profiles.json').catch(()=>null),read('metered-evidence.json').catch(()=>null),read('satellite-evidence.json').catch(()=>null),read('drc-benchmark.json').catch(()=>null),read('solar-resource.json').catch(()=>null)]);setMeteredEvidence(metered);setDrcBenchmark(drc);sites=(Array.isArray(siteData)?siteData:siteData.sites).concat(customSites);boundaries=geo;survey=sur;catalog=cat;ramp=ram;if(ramp?.profiles)templates=Object.fromEntries(Object.entries(ramp.profiles).map(([k,v])=>[k,v.hourlyShares]));const initial=sites.filter(s=>s.candidate&&s.population>500&&s.population<2500&&s.buildings>0&&s.population/s.buildings>1.5&&s.population/s.buildings<10).sort((a,b)=>Number(b.schools||0)+Number(b.clinics||0)-Number(a.schools||0)-Number(a.clinics||0))[0]||sites[0];state.siteId=initial.id;state.inputs=defaultInputs(initial,survey);try{const stored=JSON.parse(localStorage.getItem('aimenergy.session')||'null');if(stored&&sites.some(s=>String(s.id)===String(stored.siteId))){state.siteId=stored.siteId;state.inputs=stored.inputs||defaultInputs(site(),survey);state.populationOverride=stored.populationOverride;state.mlSource=stored.mlSource;state.fieldEvidence=stored.fieldEvidence;}}catch{}await initRemoteLab({getContext:()=>({site:siteForModel(),boundary:boundaries.features.find(f=>String(f.id??f.properties.id)===String(state.siteId))}),render:()=>{if(state.view==='remote')render();},onPilot:id=>{if(!id)return;selectSite(id);state.view='remote';render();},onField:()=>{state.view='field';render();},notify:toast},remote);initSystemLab({getSite:()=>siteForModel(),getDemand:()=>calculate(),render:()=>{if(state.view==='system')render();},onPilot:id=>{if(String(state.siteId)!==String(id))selectSite(id);state.view='system';render();}},solar);initCommunityLab({getSites:()=>sites,getSite:()=>siteForModel(),render:()=>{if(['community','field'].includes(state.view))render();},onField:id=>{if(String(state.siteId)!==String(id))selectSite(id);state.view='field';render();}});initFieldLab({getContext:()=>({site:siteForModel(),sourceSite:site(),inputs:state.inputs,mlSource:state.mlSource,fieldEvidence:state.fieldEvidence,mlSchema:getMLEvidence().feature_schema,profileProvenance:ramp?.provenance,profiles:templates}),notify:toast,onApply:record=>{const revised=assessmentValues(record);state.inputs=revised.inputs;state.populationOverride=revised.site.population;state.mlSource=record.answers.householdKWhPerMonth?null:record.baseline.mlSource;state.fieldEvidence=record;state.view='field';persist();render();}});await initAILab({getContext:()=>({site:siteForModel(),inputs:state.inputs,result}),onApply:evidence=>{state.inputs.householdKWhPerMonth=evidence.value;state.mlSource=evidence;state.view='overview';render();persist();toast('Applied the survey-proxy model as an explicit household scenario.');window.scrollTo({top:0,behavior:'smooth'});}});const requestedView=window.location.hash.slice(1);if(navs.some(n=>n[0]===requestedView))state.view=requestedView;render();window.AimEnergy={getState:()=>({site:siteForModel(),inputs:state.inputs,result,profileEngine:ramp?.provenance?.engine||'Explicit shapes'}),calculateDemand};}catch(err){$('#app').innerHTML='<div class="boot"><div class="boot-mark">ϟ</div><h1>AimEnergy</h1><p>We couldn’t load the village data.</p><p>'+escapeHtml(err.message)+'</p><p>Run the included local server, then open its printed address.</p><button class="btn primary" onclick="location.reload()">Try again</button></div>';console.error(err);}}
boot();

function scrollActiveMobile(){const nav=document.querySelector(".mobile-menu"),active=nav?.querySelector(".active");if(nav?.clientWidth&&active)nav.scrollLeft=active.offsetLeft-(nav.clientWidth-active.clientWidth)/2;}
window.addEventListener("resize",scrollActiveMobile);
